import React, { useEffect, useState, useMemo } from 'react';
import { getFiles } from '../services/api';
import { Line } from 'react-chartjs-2';
import { Activity } from 'lucide-react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Tooltip,
  Legend
} from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Tooltip, Legend);

const Performance = () => {
  const [files, setFiles] = useState([]);

  useEffect(() => {
    const load = async () => {
      try {
        const res = await getFiles();
        setFiles(res.data || []);
      } catch {}
    };
    load();
  }, []);

  const getTotal = (f) => f?.metrics?.total_ms ?? f?.metrics?.total ?? null;

  // ============================================================
  // BUILD FAIR COMPARISON SET (same filename, both modes)
  // ============================================================

  const comparison = useMemo(() => {
    const map = {};

    files.forEach(f => {
      if (!map[f.filename]) map[f.filename] = {};
      map[f.filename][f.mode] = getTotal(f);
    });

    return Object.entries(map).map(([filename, modes]) => ({
      filename,
      hybrid: modes.hybrid ?? null,
      rsa: modes.rsa ?? null,
    }));
  }, [files]);

  const labels = comparison.map(f =>
    f.filename.length > 15 ? f.filename.slice(0, 15) + "..." : f.filename
  );

  const pqcData = comparison.map(f => f.hybrid);
  const rsaData = comparison.map(f => f.rsa);

  // ============================================================
  // FAIR AVERAGES (only where BOTH exist)
  // ============================================================

  const validPairs = comparison.filter(f => f.hybrid != null && f.rsa != null);

  const avgPqc = validPairs.length
    ? (validPairs.reduce((a, f) => a + f.hybrid, 0) / validPairs.length).toFixed(2)
    : "N/A";

  const avgRsa = validPairs.length
    ? (validPairs.reduce((a, f) => a + f.rsa, 0) / validPairs.length).toFixed(2)
    : "N/A";

  // ============================================================

  const lineChartData = {
    labels,
    datasets: [
      {
        label: 'Hybrid PQC',
        data: pqcData,
        borderColor: '#00ff9d',
        backgroundColor: '#00ff9d',
        borderWidth: 2,
        tension: 0.4,
        spanGaps: false
      },
      {
        label: 'RSA Baseline',
        data: rsaData,
        borderColor: '#a855f7',
        backgroundColor: '#a855f7',
        borderWidth: 2,
        tension: 0.4,
        spanGaps: false
      }
    ]
  };

  return (
    <div className="p-8 h-full space-y-6 overflow-y-auto custom-scrollbar">

      {/* HEADER */}
      <div className="flex justify-between items-center border-b border-gray-800 pb-4">
        <div>
          <h2 className="text-2xl font-bold text-white">Performance Monitor</h2>
          <p className="text-gray-500 text-xs font-mono uppercase">
            Fair Comparative Analysis (paired samples only)
          </p>
        </div>

        <div className="text-right">
          <span className="text-xs text-gray-500 uppercase">Total Files</span>
          <p className="text-2xl font-mono text-white">{files.length}</p>
        </div>
      </div>

      {/* GRAPH */}
      <div className="bg-scifi-panel border border-scifi-border p-6 rounded-xl">
        <h3 className="text-gray-400 text-xs uppercase tracking-wider mb-6 flex items-center gap-2">
          <Activity size={16} /> Latency Comparison
        </h3>

        <div className="h-80">
          <Line
            data={lineChartData}
            options={{
              responsive: true,
              maintainAspectRatio: false,
              plugins: {
                tooltip: {
                  callbacks: {
                    title: (items) => comparison[items[0].dataIndex]?.filename
                  }
                },
                legend: { labels: { color: '#fff' } }
              },
              scales: {
                y: { grid: { color: '#222' } },
                x: { grid: { display: false } }
              }
            }}
          />
        </div>
      </div>

      {/* AVERAGES */}
      <div className="grid grid-cols-2 gap-4">
        <Card title="Average PQC (paired)" value={avgPqc === "N/A" ? "N/A" : `${avgPqc} ms`} color="text-neon-green"/>
        <Card title="Average RSA (paired)" value={avgRsa === "N/A" ? "N/A" : `${avgRsa} ms`} color="text-purple-400"/>
      </div>

      {/* RAW DATA */}
      <div className="text-xs text-gray-500 font-mono">
        Only files executed in BOTH modes are used for averages.
      </div>

    </div>
  );
};

const Card = ({ title, value, color }) => (
  <div className="bg-black/40 border border-gray-800 p-4 rounded flex justify-between">
    <span className="text-gray-400">{title}</span>
    <span className={`font-bold ${color}`}>{value}</span>
  </div>
);

export default Performance;
